import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.ReentrantLock;
import java.io.IOException;

public class NIOBufferChannelPool {
    private final ReentrantLock lock = new ReentrantLock(true);
    private final Condition notFull = lock.newCondition();
    private final Condition notEmpty = lock.newCondition();
    private final ByteBuffer[] bufferPool;
    private int count = 0, putIndex = 0, takeIndex = 0;

    public NIOBufferChannelPool(int capacity) {
        this.bufferPool = new ByteBuffer[capacity];
    }

    public void put(ByteBuffer data) throws InterruptedException, IOException {
        lock.lock();
        try {
            while (count == bufferPool.length) {
                notFull.await(); // Releases lock safely, handles NIO buffer backpressure
            }
            bufferPool[putIndex] = data;
            if (++putIndex == bufferPool.length) putIndex = 0;
            count++;
            notEmpty.signal(); // Wake up consumers waiting for data
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new IOException("Channel pool put operation interrupted", e);
        } finally {
            lock.unlock();
        }
    }
}
